'use strict';
const jwt = require('jsonwebtoken');

// BR-01 (AS-04 gap): see the notes-api / leave-management demo projects for the same
// documented HS256-if-configured, else structurally-valid-token fallback.
function auth(req, res, next) {
  const header = req.headers.authorization || '';
  const token = header.startsWith('Bearer ') ? header.slice(7) : null;
  if (!token) return res.status(401).json({ error: 'unauthorized', message: 'missing Authorization header' });

  try {
    const secret = process.env.JWT_SECRET;
    const payload = secret ? jwt.verify(token, secret) : jwt.decode(token);
    if (!payload || !payload.sub) {
      return res.status(401).json({ error: 'unauthorized', message: 'token missing sub' });
    }
    if (payload.exp && Date.now() >= payload.exp * 1000) {
      return res.status(401).json({ error: 'unauthorized', message: 'token expired' });
    }
    next();
  } catch {
    return res.status(401).json({ error: 'unauthorized', message: 'invalid token' });
  }
}

module.exports = auth;

'use strict';
const express = require('express');
const Item = require('../models/Item');
const auth = require('../middleware/auth');

const router = express.Router();

// API-01 (BR-01, BR-04)
router.post('/items', auth, async (req, res) => {
  const { name, unit, reorder_threshold } = req.body || {};
  if (!name || typeof name !== 'string' || !unit || typeof unit !== 'string') {
    return res.status(422).json({ error: 'invalid_request', message: 'name and unit are required' });
  }
  const existing = await Item.findOne({ name: name.toLowerCase() });
  if (existing) return res.status(409).json({ error: 'duplicate_item' });

  const doc = await Item.create({
    name: name.toLowerCase(),
    unit,
    reorder_threshold: typeof reorder_threshold === 'number' ? reorder_threshold : 0,
  });
  res.status(201).json({ id: doc._id, name: doc.name, current_stock: doc.current_stock });
});

// API-02 (BR-01)
router.get('/items', auth, async (req, res) => {
  const items = await Item.find().sort({ name: 1 }).lean();
  res.json({ items });
});

// API-04 (BR-01, BR-05) — registered BEFORE the (absent) /items/:id route on purpose:
// there is no such route here, but keeping the static path ahead of any future
// parameterised one avoids the classic Express ordering trap.
router.get('/items/low-stock', auth, async (req, res) => {
  const items = await Item.find({ $expr: { $lte: ['$current_stock', '$reorder_threshold'] } })
    .sort({ current_stock: 1 })
    .lean();
  res.json({ items });
});

module.exports = router;

'use strict';
const express = require('express');
const Item = require('../models/Item');
const StockMovement = require('../models/StockMovement');
const auth = require('../middleware/auth');

const router = express.Router();

// API-03 (BR-01, BR-02, BR-03): the only way current_stock ever changes.
router.post('/stock-movements', auth, async (req, res) => {
  const { item_id, type, quantity, note } = req.body || {};
  if (!item_id || (type !== 'in' && type !== 'out') || typeof quantity !== 'number' || quantity <= 0) {
    return res.status(422).json({ error: 'invalid_request', message: 'item_id, type (in|out), and a positive quantity are required' });
  }

  const item = await Item.findById(item_id);
  if (!item) return res.status(404).json({ error: 'not_found' });

  const delta = type === 'in' ? quantity : -quantity;
  // BR-02: an "out" movement can never take stock below zero — the guard and the
  // decrement happen in one conditional update, so two concurrent "out" posts can't
  // both succeed against the same last unit.
  const updated = await Item.findOneAndUpdate(
    { _id: item._id, current_stock: { $gte: type === 'out' ? quantity : 0 } },
    { $inc: { current_stock: delta } },
    { new: true },
  );
  if (!updated) return res.status(409).json({ error: 'insufficient_stock' });

  await StockMovement.create({ item_id: item._id, type, quantity, note });
  res.status(201).json({ id: item._id, item_id: item._id, current_stock: updated.current_stock });
});

module.exports = router;

